mapper.select:
SELECT s.id, s.title, s.category, m.name AS merchantName, s.status, s.create_time AS submitTime FROM show_info s LEFT JOIN merchant m ON s.merchant_id = m.id
AND s.status = #{status}
ORDER BY s.create_time DESC

SELECT s.id, s.title, s.category, s.cover_url, s.status, v.name AS venueName, v.city, (SELECT MIN(tc.price) FROM ticket_category tc WHERE tc.show_id = s.id) AS minPrice, (SELECT MIN(ss.sale_start_time) FROM show_session ss WHERE ss.show_id = s.id AND ss.sale_start_time > NOW()) AS saleStartTime FROM show_info s LEFT JOIN venue v ON s.venue_id = v.id
AND s.status IN (3, 4)
AND s.category = #{q.category}
AND v.city = #{q.city}
AND s.title LIKE CONCAT('%', #{q.keyword}, '%')
ORDER BY s.id DESC
